- dp_fn JavaScriptFunction «What the press changes» {"uses":"game/dispatch,game/actions,game/save,game/text,view/run,view/common,view/formation,view/prep,settings/check,rules/data,rules/engine,rules/plan","runOnChange-in-act":false,"runOnChange-in-arg":false,"runOnChange-in-save":false,"runOnChange-in-ui":false,"runOnChange-in-res":false,"runOnChange-in-live":false,"runOnChange-in-words":false,"runOnChange-in-stage":false,"scriptOutputs":[{"id":"save","label":"save"},{"id":"saveChanged","label":"saveChanged"},{"id":"ui","label":"ui"},{"id":"uiChanged","label":"uiChanged"},{"id":"res","label":"res"},{"id":"resChanged","label":"resChanged"},{"id":"live","label":"live"},{"id":"liveChanged","label":"liveChanged"},{"id":"toast","label":"toast"},{"id":"toastChanged","label":"toastChanged"}],"outtype-save":"object","outtype-saveChanged":"signal","outtype-ui":"object","outtype-uiChanged":"signal","outtype-res":"object","outtype-resChanged":"signal","outtype-live":"object","outtype-liveChanged":"signal","outtype-toast":"object","outtype-toastChanged":"signal","functionScript":"if (!Inputs.save) return;\nconst w = Scripts.text.words(Inputs.words || [], Inputs.save.lang || 'fr');\nconst ui = { ...(Inputs.ui || {}), res: Inputs.res || null, live: Inputs.live || null };\nconst r = Scripts.dispatch.dispatch(Inputs.act, Inputs.arg, Inputs.save, ui, w, Inputs.stage) || {};\nif (r.save) { Outputs.save = r.save; Outputs.saveChanged(); }\nif (r.ui) {\n  const { res, live, ...patch } = r.ui;\n  if ('res' in r.ui) { Outputs.res = res; Outputs.resChanged(); }\n  if ('live' in r.ui) { Outputs.live = live; Outputs.liveChanged(); }\n  if (Object.keys(patch).length) { Outputs.ui = patch; Outputs.uiChanged(); }\n}\nif (r.toast) { Outputs.toast = { text: r.toast, n: Date.now() }; Outputs.toastChanged(); }\n"}
