  code = code.replace(/^import\s*\{([^}]*)\}\s*from\s*'\.\/(\w+)\.js';/gm, (_, list, file) => `const {${list}} = use('rules/${file}');`);
  code = code.replace(/^export (const|let|function) (\w+)/gm, (_, kind, id) => { names.push(id); return `${kind} ${id}`; });
