content.content:
--- gp_view 
const lang = (Inputs.save && Inputs.save.lang) || 'fr';
const w = Scripts.text.words([...(Inputs.words || []), ...(Inputs.gwords || [])], lang);
const G = Scripts.grownups;
const roles = (Inputs.roles || []).map((r) => (typeof r === 'string' ? r : r && (r.name || (r.get && r.get('name')))));
const signedIn = !!Inputs.authenticated, grownup = signedIn && roles.includes('grownup');
const table = G.TABLE_KEYS.includes(Inputs.table) ? Inputs.table : 'moves';
Outputs.title = w('g_title'); Outputs.intro = w('g_intro'); Outputs.back = w('g_back');
Outputs.message = Inputs.message || '';
Outputs.needSignIn = !signedIn; Outputs.notGrownup = signedIn && !grownup; Outputs.isGrownup = grownup;
Outputs.siH = w('g_signinH'); Outputs.user = w('g_user'); Outputs.pass = w('g_pass'); Outputs.login = w('g_login'); Outputs.signup = w('g_signup'); Outputs.siHint = w('g_signupHint');
Outputs.notGText = w('g_notGrownup'); Outputs.logout = w('g_logout'); Outputs.who = w('g_signedAs', Inputs.username || '');
Outputs.tables = G.tables(table, w); Outputs.applyNote = w('g_applyNote'); Outputs.openGame = w('g_openGame');
Outputs.rows = G.rows(table, Inputs.changes || [], w).map((r) => ({ ...r, saveLabel: w('g_save'), resetLabel: w('g_reset'), frLabel: w('gf_fr'), enLabel: w('gf_en') }));
Outputs.isStart = table === 'start'; Outputs.startH = w('g_startH'); Outputs.startHint = w('g_startHint'); Outputs.stars = String(Scripts.data.START.stars); Outputs.save = w('g_save');
Outputs.isMoves = table === 'moves'; Outputs.isOutfits = table === 'outfits';
Outputs.savedText = w('g_saved'); Outputs.removedText = w('g_removed');
const o = G.options(w);
Outputs.nsTitle = w('g_newStepH'); Outputs.ncTitle = w('g_newCostumeH'); Outputs.add = w('g_add');
Outputs.frL = w('gf_fr'); Outputs.enL = w('gf_en'); Outputs.dL = w('gf_d'); Outputs.cL = w('gf_c'); Outputs.iconL = w('gf_icon'); Outputs.stL = w('gf_st'); Outputs.aL = w('gf_a'); Outputs.bL = w('gf_b'); Outputs.minL = w('gf_min'); Outputs.priceL = w('gf_price'); Outputs.themeL = w('gf_theme');
Outputs.diffs = o.diffs; Outputs.counts = o.counts; Outputs.icons = o.icons; Outputs.styles = o.styles; Outputs.levels = o.levels; Outputs.themes = o.themes;

--- gp_said 
const lang = (Inputs.save && Inputs.save.lang) || 'fr';
const w = Scripts.text.words([...(Inputs.words || []), ...(Inputs.gwords || [])], lang);
const e = String(Inputs.error || '');
const key = `gm_${e}`;
Outputs.message = w.has(key) ? w(key) : e ? `${w('gm_network')} (${e.slice(0, 80)})` : w('gm_network');
Outputs.said();

--- gp_change 
const lang = (Inputs.save && Inputs.save.lang) || 'fr';
const w = Scripts.text.words([...(Inputs.words || []), ...(Inputs.gwords || [])], lang);
const G = Scripts.grownups;
const at = (v) => (v && v.at) || 0;
const latest = Math.max(at(Inputs.rowValues), at(Inputs.stepValues), at(Inputs.costumeValues));
let c = null;
if (latest && latest === at(Inputs.rowValues)) c = G.rowChange(Inputs.table || 'moves', Inputs.rowId, Inputs.rowValues);
else if (latest && latest === at(Inputs.stepValues)) c = G.newStep(Inputs.stepValues);
else if (latest && latest === at(Inputs.costumeValues)) c = G.newCostume(Inputs.costumeValues);
const p = G.precheck(c, w);
if (!p.ok) { Outputs.message = p.message; Outputs.said(); return; }
Outputs.table = c.table; Outputs.rowId = c.rowId; Outputs.fields = c.fields;
Outputs.send();

