input.command:
grep -rn "fromRound1\|gala-game\|storageKey" app tools gala-rules --include=* 2>/dev/null | grep -v "^app/scripts/game/save.js:1[0-9]:" | cut -c1-200; cat > /tmp/gala-tools/size.mjs <<'EOF'
import { readFileSync } from 'node:fs'; import { join } from 'node:path';
const root = process.argv[2]; const cache = {};
function use(p){ if(cache[p]) return cache[p]; const e=(cache[p]={}); new Function('exports','use',readFileSync(join(root,'app/scripts',p+'.js'),'utf8'))(e,use); return e; }
const S=use('game/save'), A=use('game/actions'), E=use('rules/engine'), T=use('game/text');
